TLM.f("Tempora/Pent13-1",{"officium":"Feria Secunda infra Hebdomadam XIII post Octavam Pentecostes","rule":["Oratio Dominica","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"ruleInherited":["Gloria","Credo","Prefatio=Trinitate","Suffr=Sanctorum;Maria3,Ecclesiæ,Papa;;"],"fallback":"Tempora/Pent13-0","from":{"Introitus":"Tempora/Pent13-0","Oratio":"Tempora/Pent13-0","Lectio":"Tempora/Pent13-0","Graduale":"Tempora/Pent13-0","Evangelium":"Tempora/Pent13-0","Offertorium":"Tempora/Pent13-0","Secreta":"Tempora/Pent13-0","Communio":"Tempora/Pent13-0","Postcommunio":"Tempora/Pent13-0"},"sections":{"Introitus":[{"k":"ref","la":"Ps 73:20; 73:19; 73:23"},{"k":"text","la":"Réspice, Dómine, in testaméntum tuum, et ánimas páuperum tuórum ne derelínquas in finem: exsúrge, Dómine, et júdica causam tuam, et ne obliviscáris voces quæréntium te."},{"k":"ref","la":"Ps 73:1"},{"k":"text","la":"Ut quid, Deus, reppulísti in finem: irátus est furor tuus super oves páscuæ tuæ?"},{"k":"macro","name":"Gloria"},{"k":"text","la":"Réspice, Dómine, in testaméntum tuum, et ánimas páuperum tuórum ne derelínquas in finem: exsúrge, Dómine, et júdica causam tuam, et ne obliviscáris voces quæréntium te."}],"Oratio":[{"k":"text","la":"Omnípotens sempitérne Deus, da nobis fídei, spei et caritátis augméntum: et, ut mereámur asséqui quod promíttis, fac nos amáre quod prǽcipis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Gálatas"},{"k":"ref","la":"Gal 3:16-22"},{"k":"text","la":"Fratres: Abrahæ dictæ sunt promissiónes, et sémini ejus. Non dicit: Et semínibus, quasi in multis; sed quasi in uno: Et sémini tuo, qui est Christus. Hoc autem dico: testaméntum confirmátum a Deo, quæ post quadringéntos et trigínta annos facta est lex, non írritum facit ad evacuándam promissiónem. Nam si ex lege heréditas, jam non ex promissióne. Abrahæ autem per repromissiónem donávit Deus. Quid igitur lex? Propter transgressiónes pósita est, donec veníret semen, cui promíserat, ordináta per Angelos in manu mediatóris. Mediátor autem uníus non est: Deus autem unus est. Lex ergo advérsus promíssa Dei? Absit. Si enim data esset lex, quæ posset vivificáre, vere ex lege esset justítia. Sed conclúsit Scriptúra ómnia sub peccáto, ut promíssio ex fide Jesu Christi darétur credéntibus."}],"Graduale":[{"k":"ref","la":"Ps 73:20; 73:19; 73:22"},{"k":"text","la":"Réspice, Dómine, in testaméntum tuum: et ánimas páuperum tuórum ne obliviscáris in finem."},{"k":"text","la":"Exsúrge, Dómine, et júdica causam tuam: memor esto oppróbrii servórum tuórum. Allelúja, allelúja","mark":"V"},{"k":"ref","la":"Ps 89:1"},{"k":"text","la":"Dómine, refúgium factus es nobis a generatióne et progénie. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 17:11-19"},{"k":"text","la":"In illo témpore: Dum iret Jesus in Jerúsalem, transíbat per médiam Samaríam et Galilǽam. Et cum ingrederétur quoddam castéllum, occurrérunt ei decem viri leprósi, qui stetérunt a longe; et levavérunt vocem dicéntes: Jesu præcéptor, miserére nostri. Quos ut vidit, dixit: Ite, osténdite vos sacerdótibus. Et factum est, dum irent, mundáti sunt. Unus autem ex illis, ut vidit quia mundátus est, regréssus est, cum magna voce magníficans Deum, et cecidit in fáciem ante pedes ejus, grátias agens: et hic erat Samaritánus. Respóndens autem Jesus, dixit: Nonne decem mundáti sunt? et novem ubi sunt? Non est invéntus, qui redíret et daret glóriam Deo, nisi hic alienígena. Et ait illi: Surge, vade; quia fides tua te salvum fecit."}],"Offertorium":[{"k":"ref","la":"Ps 30:15-16"},{"k":"text","la":"In te sperávi, Dómine; dixi: Tu es Deus meus, in mánibus tuis témpora mea."}],"Secreta":[{"k":"text","la":"Propitiáre, Dómine, pópulo tuo, propitiáre munéribus: ut, hac oblatióne placátus, et indulgéntiam nobis tríbuas et postuláta concedas."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Sap 16:20"},{"k":"text","la":"Panem de cœlo dedísti nobis, Dómine, habéntem omne delectaméntum et omnem sapórem suavitátis."}],"Postcommunio":[{"k":"text","la":"Sumptis, Dómine, cœléstibus sacraméntis: ad redemptiónis ætérnæ, quǽsumus, proficiámus augméntum."},{"k":"macro","name":"Per Dominum"}]},"hr":{"f03985903daa2a5d":{"t":"Ps 73, 20, 19 i 23, Ps 73, 1\n(Ps 73, 20, 19 i 23) Pogledaj, Gospodine, na svoj zavjet i duše siromaha svojih ne zaboravi dokraja. Ustani, Gospodine, brani stvar svoju, ne ogluši se na glasove onih koji te traže. (Ps 73, 1) Zašto si nas, Bože, odbacio za vazda? Zašto se raspalio tvoj gnjev na ovce paše tvoje?\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 73, 20, 19 i 23) Pogledaj, Gospodine, na svoj zavjet i duše siromaha svojih ne zaboravi dokraja. Ustani, Gospodine, brani stvar svoju, ne ogluši se na glasove onih koji te traže.","kn":"(Ps. 73, 29). Pogledaj, Gospodine, na zavjet svoj, i duše, ubogih svojih ne zapusti do kraja. Ustani, . Gosipodine, i sudi pravdu moj:u, i ne zaboravi vapaj onih, koji Te, ištu. (Ps. 73, 1) Zašto, BO'že, otjera .do kraja, zašto se izli gnjev Tvoj na ovce paše Tvoje? Slava Ocu . . . Pogledaj ...","knRef":"Kniewald 1942, str. 396–397 (snimka 199) (OCR)"},"f924a6de3ba45f4c":{"t":"<i>Pomolimo se</i>.\nSvemogući vječni Bože, daj da nam poraste vjera, ufanje i ljubav, te učini da ljubimo što zapovijedaš, da bismo postigli što obećavaš.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Svemogući,-, vječni Bože, umnoži nam vjeru, ufanje iljubav i da zaslužimo dostignuti, što o-bećavaš, - učini, da ljubimo, što , zapovijedaš, po Gospodinu našemu.","knRef":"Kniewald 1942, str. 396–397 (snimka 199) (OCR)"},"e18934ddbe6dec3a":{"t":"Gal 3, 16-22\nČitanje Poslanice bl. Pavla apostola Galaćanima. Braćo, Abrahamu i njegovu potomku bila su zadana obećanja. Ne kaže: i potomcima kao mnogima, nego kao jednome: I tvojem potomku, koji je Krist. A kažem ovo: Zakon koji je nastao poslije četiri stotine i trideset godina ne ukida zavjeta koji je potvrđen od Boga, da bi tako poništio obećanje. Ako je nasljedstvo po zakonu, onda nije po obećanju, a Bog je Abrahamu dao po obećanju. – Čemu dakle zakon? Zakon, objavljen od anđela preko posrednika, dan je da se jače vide prestupci dok ne dođe potomak za kojega su dana obećanja. Posrednika nema, ako postoji samo jedna strana, a Bog je jedan. Je li dakle zakon protivan Božjim obećanjima? Nipošto. Doista, da je dan zakon koji bi mogao davati život, pravda bi ovisila o zakonu. Ali prema Pismu sve je podložno grijehu, da se vjernicima obećanje ostvari po vjeri u Isusa Krista.","kn":"Čitanje poslanice bi, Pavla apostola Galaeanima (3,, 16-22). , Braćo! Obećanja bila su dana Abrahamu i njegovu potomku. Ne, kaže: I potomcima, kao b m.np-gima, nego kao, o jednomu; 1 tvo-jemu potomku, koji je Krist. Ovo pak kažem: Zakon, koji je postao poslije četirista i trideset . godina, zavjeta., koji je potvrđen od Boga, ne ukida tako, da bi uništio obećanje. Jer ako je nasljedstvo p6 zakonu, tada Već nije po obećanju. A Abrahatnu je darovao Bog po obećanju. CemU dakle zakon? Postavljen je radi p.restupka do dolaska potomka, kojemu je dano obećanje i objavljen je po anđelima preko posrednika, A posrednik nije posrednik samo za jednoga, dok je Bog jedan. Je li dakle zakon protiv Božjih obećanja? Nikako. Jer da je postavljen zakon, koji bi mogao davati život, pravda bi zaista ovisUa o zakonu. Ali po Pisanu sve je podložno grijehu, da se onima, koji vjeruju, dade obećanje po vjeri u Isusa Krista. ,","knRef":"Kniewald 1942, str. 396–397 (snimka 199) (OCR)"},"278fa3e553d7e605":{"t":"Ps 73, 20 i 19 i 22\nPogledaj, Gospodine, na svoj zavjet i duše siromaha svojih ne zaboravi dokraja. Ustani, Gospodine, brani stvar svoju, spomeni se sramote slugu svojih.\n\nPs 89, 1\n<i>Aleluja</i>, <i>aleluja</i>.\nBože, ti si nam bio utočište od koljena do koljena. <i>Aleluja</i>.","kn":"IPs. 73, 20, 19, 22). Pogledaj, Gospodine, na zavjet svoj, i ne zaboravi do kraja svojih ubogih. Ustani, Gospodine, sudi pravdu svoju, sjeti se sramote slugu svojih!\n\nAleluja, aleluja. P (s. 89, 1) Gospodine, postao si hama utočište od koljena do koljena, aleluja,","knRef":"Kniewald 1942, str. 186–187 (snimka 94) (OCR)"},"c12bbf19a77e625c":{"t":"Lk 17, 11-19\nSlijedi sveto Evanđelje po Luki. U ono vrijeme idući Isus prema Jeruzalemu prolazio je između Samarije i Galileje. Kad je ulazio u neko selo, dočeka ga deset gubavaca. Oni su stajali podalje i vapili: Isuse, učitelju, smiluj se nama! Isus ih opazi i reče im: Idite, pokažite se svećenicima. I dok su išli, očiste se od gube. Tada jedan od njih, čim vidje da je ozdravio, vrati se glasno slaveći Boga i padne ničice pred njega i zahvali mu. I taj je bio Samaritanac. Tada Isus upita: Zar ih se nije očistilo deset? Gdje je ostalih devet? Nitko se ne vrati, da poda slavu Bogu, osim ovog tuđinca! Onda mu reče: Ustani, idi, tvoja te je vjera spasila.","v":"et → ∅","kn":"t Slijedi sveto evanđelje po Laki (17, 11-19). U ono vrijeme, kad je Isus putovao u Jeruzalem, prolazio je kroz Samariju i Galileju. I kad je ulazio u neko selo, susietne ga deset gubavaca, koji su podalje stajali i vikali: Isuse, učitelju, smiluj nam se! Kad ih je vidio, reče: Idite, pokažite se svećenicima! I dole su išli očistiše se. Kad jedan od njih opazi, da se 'očistio, povrati se i na sav glas hvaleći Boga padne ničice preda nj i zahvali mu; a taj je bio Samaritana'C. Isus tada upita: Zar ih se nije očistilo deset? A gdje je ostalih devet? Nitko se ne nađe, da se vrati i zahvali Bogu, osim ovoga tuđinca. Nato mu reče: Ustani, idi, jer ti je pomogla tvoja vjera!","knRef":"Kniewald 1942, str. 398–399 (snimka 200) (OCR)"},"23887187251b9760":{"t":"Ps 30, 15-16\nJa se uzdam u tebe, Gospodine! Govorim: Ti si Bog moj, u tvojim je rukama sudbina moja.","kn":"Prikazaiye (Ps. 30, 15). U Tebe se Gospodine, uzdah i rAoh: Ti si Bog moj, Vu. Tvojim su rukama vremena moja.","knRef":"Kniewald 1942, str. 840–841 (snimka 421) (OCR)"},"85702ff26e4d340b":{"t":"Budi, Gospodine, milostiv svome narodu, pogledaj milostivo ove darove i primi ih kao pomirbeni dar te nam daj oproštenje i udijeli što molimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":", Milostiv budi. Gospodine, narodu svojemu, milostiv budi darovima, da nara ublažen ovim prinosom i oproštenje dadeš, i što ištemo, udijeliš, po G. n.","knRef":"Kniewald 1942, str. 398–399 (snimka 200) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"16807625d475b4fe":{"t":"Mudr 16, 20\nKruh s neba dao si nam, Gospodine, koji u sebi ima svaku slast i svu ugodnost.","kn":"(Mudr. 16, 20). Hljeb s nebesa dade nam Gospodine, koji svaku slast ima u sobi i svaki okus ljupkosti.","knRef":"Kniewald 1942, str. 398–399 (snimka 200) (OCR)"},"e925bfac9b30685f":{"t":"<i>Pomolimo se</i>.\nMolimo, Gospodine, da po primljenim nebeskim otajstvima sve više napredujemo k vječnom otkupljenju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primivši, Gospodine, nebeske tajne molimo, da u nama sve više umnažaš milost vječnog otkupljenja, po G. n.","knRef":"Kniewald 1942, str. 398–399 (snimka 200) (OCR)"}}});
